import net.sf.jsqlparser.JSQLParserException;
import net.sf.jsqlparser.statement.Statement;
import net.sf.jsqlparser.statement.select.Select;
import net.sf.jsqlparser.util.ccjjyy.PageException;

public String convertToPageSql(String sql, Integer offset, Integer limit) {
    // Ensure the provided SQL query is a SELECT query
    if (!sql.trim().toUpperCase().startsWith("SELECT")) {
        throw new PageException("分页语句必须是Select查询!");
    }

    // Parse SQL
    Statement stmt;
    try {
        stmt = jSqlParser.parse(sql);
    } catch (JSQLParserException e) {
        throw new PageException("不支持该SQL转换为分页查询!", e);
    }

    if (!(stmt instanceof Select)) {
        throw new PageException("分页语句必须是Select查询!");
    }

    // Get the select query for pagination
    Select pageSelect = (Select) stmt;
    String pageSql = pageSelect.toString();

    // Replace the placeholders with offset and limit values
    if (offset != null) {
        pageSql = pageSql.replace(START_ROW, String.valueOf(offset));
    }

    if (limit != null) {
        pageSql = pageSql.replace(PAGE_SIZE, String.valueOf(limit));
    }

    return pageSql;
}

